@Inject(method = "setupRotations", at = @At("TAIL"))
private void godwand$dominionFlightRotations(net.minecraft.client.renderer.entity.state.LivingEntityRenderState state,
                                             PoseStack matrices, float yaw, float scale, CallbackInfo ci) {
    if (state instanceof net.minecraft.client.renderer.entity.state.HumanoidRenderState humanoid) {
        var level = net.minecraft.client.Minecraft.getInstance().level;
        var entity = level == null ? null : level.getEntity(net.godwand.client.AtomicPoseFrames.entityId(humanoid));
        if (entity instanceof LivingEntity living) {
            BlockDominionPose.applyBodyRotations(living, matrices, net.godwand.client.AtomicPoseFrames.partial(humanoid));
        }
    }
}
